//! Nullable ARIA strings retain authoritative native UTF-16 code units.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><p id=target></p><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://aria-units.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn aria_domstring_reflection_reads_actual_inert_units_without_replacement_alias(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.documentElement;source.setAttribute('aria-label','A\ud800z');var descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'ariaLabel'),a=source.getAttributeNode('aria-label');if(source.ariaLabel!=='A\ud800z'||descriptor.get.call(source)!==a.value||source.ariaLabel==='A�z'||source.ariaLabel.charCodeAt(1)!==0xd800)throw 'native nullable raw getter';Object.defineProperty(source,'ariaLabel',{get:function(){return 'author';},configurable:true});if(source.ariaLabel!=='author'||descriptor.get.call(source)!=='A\ud800z')throw 'native ignores own author shadow';delete source.ariaLabel;if(source.ariaLabel!=='A\ud800z')throw 'native fallback';"#);}
#[test]
fn aria_domstring_reflection_inert_setters_keep_null_namespace_attr_and_removal(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument('urn:original','p:Root'),source=owner.documentElement;source.setAttributeNS('urn:attribute','aria-label','foreign');var foreign=source.getAttributeNodeNS('urn:attribute','aria-label'),descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'ariaLabel'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});source.ariaLabel='A\ud800z';var a=source.getAttributeNodeNS(null,'aria-label');if(source.ariaLabel!=='A\ud800z'||a===null||a===foreign||a.value!==source.ariaLabel||foreign.value!=='foreign')throw 'exact null namespace nullable setter';descriptor.set.call(source,'B\udfffz');source.ariaLabel=null;var records=watch.takeRecords();if(source.ariaLabel!==null||a.ownerElement!==null||a.value!=='B\udfffz'||foreign.ownerElement!==source||foreign.value!=='foreign'||records.length!==3||records[0].oldValue!==null||records[0].attributeNamespace!==null||records[1].oldValue!=='A\ud800z'||records[2].oldValue!=='B\udfffz')throw 'native nullable removal';source.ariaLabel=undefined;descriptor.set.call(source);if(source.ariaLabel!==null||watch.takeRecords().length)throw 'missing nullable native value';source.ariaLabel='';if(source.ariaLabel!==''||source.getAttributeNS(null,'aria-label')!=='')throw 'present empty';"#);}
#[test]
fn aria_domstring_reflection_no_slot_clone_and_adopt_keep_actual_sources(){let(mut d,mut f,mut p)=fixture();let limit=p.state.node_limit;let count=d.nodes.len();p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('urn:original','p:Root'),target=document.implementation.createDocument(null,'Root');source.ariaLabel='A\ud800z';source.role='R\udfffz';var a=source.getAttributeNodeNS(null,'aria-label'),copy=source.cloneNode(true),imported=target.importNode(source,true);if(copy===source||copy.ariaLabel!==source.ariaLabel||copy.role!==source.role||copy.ownerDocument!==owner||imported.ariaLabel!==source.ariaLabel||imported.ownerDocument!==target)throw 'independent native nullable copies';target.adoptNode(source);source.ariaLabel='fresh';if(source.getAttributeNodeNS(null,'aria-label')!==a||a.ownerDocument!==target||a.value!=='fresh'||source.ownerDocument!==target||copy.ariaLabel!=='A\ud800z'||imported.ariaLabel!=='A\ud800z')throw 'adopted native Attr and independent copies';"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=limit;}

#[test]
fn aria_domstring_reflection_displayed_native_getter_bounds_and_raw_writer_guard(){let(mut d,mut f,mut p)=fixture();let target=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("target")).unwrap();let NodeKind::Element{attrs,..}=&mut d.nodes[target].kind else{unreachable!()};attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("aria-label".into()),value:DomString::from_units(&[65,0xd800,122],4096).unwrap()});run(&mut d,&mut f,&mut p,"var source=document.getElementById('target'),descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'ariaLabel');if(source.ariaLabel!=='A\\ud800z'||descriptor.get.call(source)!==source.getAttribute('aria-label')||source.ariaLabel==='A�z')throw 'displayed exact native read';var shape=document.createElementNS('http://www.w3.org/2000/svg','svg');");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let strings=p.state.limits.host.string_bytes;
for mode in 0..3{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,_=>p.state.limits.host.string_bytes=4};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.aria_reflection_get(node_handle(target),"ariaLabel").unwrap_err();assert!(error.contains("work")||error.contains("allowance"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.limits.host.string_bytes=strings;}p.begin_job();let error=p.runtime.execute("descriptor.set.call(shape,'B\\udfffz');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Unpaired attribute"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"source.ariaLabel='fresh';if(source.ariaLabel!=='fresh')throw 'scalar writer recovery';");}
#[test]
fn aria_domstring_reflection_all_registered_strings_preserve_exact_nullable_state(){let(mut d,mut f,mut p)=fixture();let pairs=crate::javascript::aria_reflection_interface::ATTRIBUTES.iter().map(|(property,key,_,_)|format!("[{property:?},{key:?}]")).collect::<Vec<_>>().join(",");run(&mut d,&mut f,&mut p,&format!(r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.documentElement,pairs=[{pairs}];for(var pair of pairs){{var property=pair[0],name=pair[1];if(source[property]!==null)throw 'actual absent nullable value';source[property]='A\ud800z';if(source[property]!=='A\ud800z'||source.getAttributeNS(null,name)!==source[property]||source[property]==='A�z')throw 'registered exact native string';source[property]=null;if(source[property]!==null||source.getAttributeNS(null,name)!==null)throw 'registered nullable removal';}}"#));}
#[test]
fn aria_domstring_reflection_conversion_reentry_symbol_and_brand_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.documentElement,descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'ariaLabel'),calls=0;try{descriptor.set.call({}, {toString:function(){calls++;return 'bad';}});throw 'brand missing';}catch(e){if(!(e instanceof TypeError))throw e;}if(calls)throw 'brand before conversion';source.setAttributeNS('urn:attribute','aria-label','foreign');var held;source.ariaLabel={toString:function(){calls++;source.setAttributeNS(null,'aria-label','effect');held=source.getAttributeNodeNS(null,'aria-label');source.setAttributeNS('urn:attribute','aria-label','updated');return 'A\ud800z';}};if(calls!==1||source.ariaLabel!=='A\ud800z'||held.value!==source.ariaLabel||source.getAttributeNodeNS(null,'aria-label')!==held||source.getAttributeNS('urn:attribute','aria-label')!=='updated')throw 'current native state after conversion';try{source.ariaLabel=Symbol();throw 'Symbol missing';}catch(e){if(!(e instanceof TypeError))throw e;}var marker={};try{source.ariaLabel={toString:function(){source.setAttribute('data-effect','retained');throw marker;}};throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(source.ariaLabel!=='A\ud800z'||source.getAttribute('data-effect')!=='retained')throw 'abrupt effects retained';source.ariaChecked=false;source.ariaValueNow=0;if(source.ariaChecked!=='false'||source.ariaValueNow!=='0')throw 'nullable DOMString conversion';"#);}

#[test]
fn aria_domstring_reflection_native_refusal_cancellation_and_recovery_preserve_both_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.documentElement;source.setAttributeNS('urn:attribute','aria-label','foreign');source.ariaLabel='A\ud800z';var a=source.getAttributeNodeNS(null,'aria-label'),foreign=source.getAttributeNodeNS('urn:attribute','aria-label'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});"#);let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits,p.state.retained);let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;
for mode in 0..5{for expression in [r#"source.ariaLabel='longB\udfffz';"#,"source.ariaLabel=null;"]{if mode==3&&!expression.contains("long"){continue;}p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=4,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits,p.state.retained),before);p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}}
p.begin_job();run(&mut d,&mut f,&mut p,r#"if(source.ariaLabel!=='A\ud800z'||a.value!==source.ariaLabel||foreign.value!=='foreign'||watch.takeRecords().length)throw 'refusal preserves exact records';source.ariaLabel='B\udfffz';source.ariaLabel=null;var records=watch.takeRecords();if(source.ariaLabel!==null||a.ownerElement!==null||a.value!=='B\udfffz'||foreign.ownerElement!==source||foreign.value!=='foreign'||records.length!==2||records[0].oldValue!=='A\ud800z'||records[1].oldValue!=='B\udfffz')throw 'fresh nullable recovery';"#);}
#[test]
fn aria_domstring_reflection_saved_child_origin_precedes_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.documentElement;source.setAttributeNS('urn:attribute','aria-label','foreign');var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'ariaLabel'),calls=0;descriptor.set.call(source,'A\ud800z');if(descriptor.get.call(source)!=='A\ud800z')throw 'actual child exact accessor';"#);let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits);p.set_location(&crate::navigation::address("https://other-aria-units.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("descriptor.set.call(source,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits),before);p.set_location(&crate::navigation::address("https://aria-units.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||source.ariaLabel!=='A\\ud800z'||source.getAttributeNS('urn:attribute','aria-label')!=='foreign')throw 'origin before conversion';descriptor.set.call(source,'fresh');if(source.ariaLabel!=='fresh')throw 'fresh origin recovery';");}
